name:
Auth page containment > async ({ page }) => {
    await page.route("**/v1/auth/config", (route) =>
      route.fulfill({
        json: {
          mode: "full",
          password_auth_enabled: true,
          oauth_providers: ["google", "github"],
          signup_enabled: true,
          signup_email_confirm: true,
        },
      }),
    );
  }

